def jlEvaluation {B : Set (Set Point)} (hB : AlmostDisjoint B) (hInf : B.Infinite)
    (p : AUCompactum B) : JL B →L[ℝ] ℝ :=
  (ContinuousMap.evalCLM ℝ p).comp (jlContinuousEquiv hB hInf).toContinuousLinearEquiv.toContinuousLinearMap

